from __future__ import annotations

import json
import os

from ledgerlock import format as fmt
from ledgerlock import store


class ConflictError(Exception):
    def __init__(self, key, incoming_rid, committed_rid, batch_index=None):
        super().__init__(
            f"conflict on key {key!r}: incoming rid {incoming_rid!r} "
            f"vs committed rid {committed_rid!r}"
        )
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index


class Ledger:
    def __init__(self, path):
        self.path = os.fspath(path)

    def append(self, operation):
        return append(self, operation)

    def verify(self):
        return verify(self)

    def snapshot(self):
        return snapshot(self)

    def apply_batch(self, operations):
        return apply_batch(self, operations)


def _parse_operation(operation):
    op = operation[0]
    if op == "put":
        if len(operation) != 5:
            raise ValueError("put requires (op, key, value, rid, ts)")
        _, raw_key, value, rid, ts = operation
        key = fmt.normalize_key(raw_key)
        if key == "":
            raise ValueError("empty key")
        return "put", key, value, rid, ts
    if op == "delete":
        if len(operation) != 4:
            raise ValueError("delete requires (op, key, rid, ts)")
        _, raw_key, rid, ts = operation
        key = fmt.normalize_key(raw_key)
        if key == "":
            raise ValueError("empty key")
        return "delete", key, None, rid, ts
    raise ValueError(f"unknown op: {op!r}")


def _build_line(op, key, value, rid, ts, prev_hash):
    if op == "put":
        fields = {"op": "put", "key": key, "value": value, "ts": ts, "id": rid}
    else:
        fields = {"op": "delete", "key": key, "ts": ts, "id": rid}
    fields["prev_hash"] = prev_hash
    fields["hash"] = fmt.line_hash(prev_hash, fields)
    return fields


def _line_bytes(line):
    return fmt.canonical_bytes(line) + b"\n"


def _parse_chain(data):
    lines = []
    index = {}
    if data == b"":
        return lines, index
    parts = data.split(b"\n")
    if parts and parts[-1] == b"":
        parts.pop()
    for part in parts:
        line = json.loads(part.decode("utf-8"))
        lines.append(line)
        index[line["key"]] = line
    return lines, index


def _read_chain(path):
    try:
        with open(path, "rb") as f:
            data = f.read()
    except FileNotFoundError:
        return [], {}
    return _parse_chain(data)


def _append_bytes(path, data):
    with open(path, "ab") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())


def append(ledger, operation):
    op, key, value, rid, ts = _parse_operation(operation)
    lines, index = _read_chain(ledger.path)
    last = index.get(key)
    if last is not None and last["id"] == rid:
        result = dict(last)
        result["replayed"] = True
        result["committed"] = False
        return result
    if last is not None:
        raise ConflictError(key, rid, last["id"], batch_index=None)
    tail = lines[-1]["hash"] if lines else fmt.GENESIS
    line = _build_line(op, key, value, rid, ts, tail)
    _append_bytes(ledger.path, _line_bytes(line))
    result = dict(line)
    result["replayed"] = False
    result["committed"] = True
    return result


def verify(ledger):
    raw_lines = store.read_lines(ledger.path)
    prev_hash = fmt.GENESIS
    for i, raw in enumerate(raw_lines):
        try:
            line = json.loads(raw.decode("utf-8"))
        except ValueError:
            return {"ok": False, "first_bad_index": i}
        if line.get("prev_hash") != prev_hash:
            return {"ok": False, "first_bad_index": i}
        stored = line.get("hash")
        if stored != fmt.line_hash(prev_hash, line):
            return {"ok": False, "first_bad_index": i}
        prev_hash = stored
    return {"ok": True, "first_bad_index": None}


def snapshot(ledger):
    lines, _ = _read_chain(ledger.path)
    state = {}
    for line in lines:
        key = line["key"]
        if line["op"] == "put":
            state[key] = line["value"]
        else:
            state.pop(key, None)
    return {k: state[k] for k in sorted(state)}


def apply_batch(ledger, operations):
    path = ledger.path
    try:
        with open(path, "rb") as f:
            existing = f.read()
    except FileNotFoundError:
        existing = b""

    lines, index = _parse_chain(existing)

    new_bytes = []
    new_lines = []
    for i, operation in enumerate(operations):
        op, key, value, rid, ts = _parse_operation(operation)
        last = index.get(key)
        if last is not None and last["id"] == rid:
            continue
        if last is not None:
            raise ConflictError(key, rid, last["id"], batch_index=i)
        tail = lines[-1]["hash"] if lines else fmt.GENESIS
        line = _build_line(op, key, value, rid, ts, tail)
        new_bytes.append(_line_bytes(line))
        new_lines.append(line)
        lines.append(line)
        index[key] = line

    if new_bytes:
        store.write_atomic(path, [existing + b"".join(new_bytes)])

    return new_lines
